def is_open(ip, port, timeout=3):
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.settimeout(timeout)
    try:
        s.connect((ip, port))
        s.shutdown(socket.SHUT_RDWR)
        return True
    except:
        return False
    finally:
        s.close()

def parse_delay(delay_args):
    if not delay_args:
        return lambda: 0  # No delay
    try:
        if len(delay_args) == 1:
            fixed = float(delay_args[0])
            return lambda: fixed
        elif len(delay_args) == 2:
            low = float(delay_args[0])
            high = float(delay_args[1])
            return lambda: random.uniform(low, high)
        else:
            sys.exit("Invalid --delay format. Use: --delay 1 or --delay 0.5 2.5")
    except:
        sys.exit("Invalid delay values. Make sure they are floats.")

def main():
    parser = argparse.ArgumentParser(description="Simple stealthy TCP port scanner")
    parser.add_argument("ip", help="Target IP address or hostname", nargs='?')
    parser.add_argument("port", help="Single port to scan", type=int, nargs='?')
    parser.add_argument("--top10", action="store_true", help="Scan top 10 common ports")
    parser.add_argument("--top50", action="store_true", help="Scan top 50 common ports")
    parser.add_argument("--top100", action="store_true", help="Scan top 100 common ports")
    parser.add_argument("--top500", action="store_true", help="Scan top 500 common ports")
    parser.add_argument("--top1000", action="store_true", help="Scan top 1000 common ports")
    parser.add_argument("--delay", nargs='*', help="Delay between scans. Examples: --delay 1 or --delay 0.5 2")

    args = parser.parse_args()

    if not args.ip:
        print("Usage: python code.py <ip> [port] [--top50|--top100|--top1000] [--delay x or x y]")
        sys.exit(1)

    delay_func = parse_delay(args.delay)

    ports = []

    if args.port:
        ports = [args.port]
    elif args.top10:
        ports = TOP_PORTS.get("top10", [])
    elif args.top50:
        ports = TOP_PORTS.get("top50", [])
    elif args.top100:
        ports = TOP_PORTS.get("top100", [])
    elif args.top500:
        ports = TOP_PORTS.get("top500", [])
    elif args.top1000:
        ports = TOP_PORTS.get("top1000", [])
    else:
        print("No ports specified. Use a port or --top50 / --top100 / --top1000.")
        sys.exit(1)

    if not ports:
        print("Port list is empty. Please fill in TOP_PORTS in the script.")
        sys.exit(1)

    random.shuffle(ports)

    print(f"[~] Starting scan on {args.ip}")
    for port in ports:
        delay_time = delay_func()
        time.sleep(delay_time)
        status = is_open(args.ip, port)
        print(f"{args.ip}:{port} => {'OPEN' if status else 'CLOSED'} (delay: {round(delay_time, 2)}s)")

if __name__ == "__main__":
    main()
